package dev.underthebedrock;
import dev.underthebedrock.command.*;import dev.underthebedrock.horror.*;import dev.underthebedrock.integration.IntegrationManager;import dev.underthebedrock.storage.PlayerLocationStore;import dev.underthebedrock.world.VoidWorldManager;import dev.underthebedrock.world.StructureManager;import dev.underthebedrock.world.SupplyDropManager;import dev.underthebedrock.item.CustomItemManager;import org.bukkit.command.PluginCommand;import org.bukkit.plugin.java.JavaPlugin;import java.util.Objects;
public final class UnderTheBedrockPlugin extends JavaPlugin {
 private VoidWorldManager worlds;private PlayerLocationStore locations;private IntegrationManager integrations;private OccurrenceDirector occurrences;private HorrorEntityController entities;private ClueManager clues;private StructureManager structures;private SupplyDropManager supplyDrops;private CustomItemManager customItems;
 @Override public void onEnable(){saveDefaultConfig();integrations=new IntegrationManager(this);if(!integrations.initialize()){getServer().getPluginManager().disablePlugin(this);return;}locations=new PlayerLocationStore(this);worlds=new VoidWorldManager(this);PlayerHorrorMemoryStore memoryStore=new PlayerHorrorMemoryStore(this);occurrences=new OccurrenceDirector(this,worlds,memoryStore);entities=new HorrorEntityController(this,worlds,occurrences,integrations.betterModel());clues=new ClueManager(this,worlds,occurrences);customItems=new CustomItemManager(this,worlds);structures=new StructureManager(this,worlds);supplyDrops=new SupplyDropManager(this,worlds);
  if(getConfig().getBoolean("horror.director.enabled",true)){occurrences.start();if(getConfig().getBoolean("horror.entities.enabled",true))entities.start();if(getConfig().getBoolean("horror.clues.enabled",true))clues.start();}
  if(getConfig().getBoolean("horror.items.enabled",true))customItems.start();
  register("enter",new EnterCommand(worlds,locations));register("leave",new LeaveCommand(locations));register("underthebedrock",new UnderTheBedrockCommand(worlds,integrations));register("evidence",new EvidenceCommand(occurrences));
  if(getConfig().getBoolean("horror.structures.enabled",true))structures.start();if(getConfig().getBoolean("horror.supply-drops.enabled",true))supplyDrops.start();
  if(getConfig().getBoolean("world.enabled-on-startup",false)&&!worlds.start())getLogger().severe("Could not initialize the configured horror world.");getLogger().info("Under The Bedrock enabled; custom equipment, structures, supply drops, and horror systems initialized.");}
 @Override public void onDisable(){if(customItems!=null)customItems.stop();if(supplyDrops!=null)supplyDrops.stop();if(structures!=null)structures.stop();if(clues!=null)clues.stop();if(entities!=null)entities.stop();if(occurrences!=null)occurrences.stop();if(locations!=null)locations.flush();}
 public OccurrenceDirector getOccurrenceDirector(){return occurrences;}public CustomItemManager getCustomItems(){return customItems;}
 private void register(String name,org.bukkit.command.CommandExecutor executor){PluginCommand c=Objects.requireNonNull(getCommand(name),"Missing command: "+name);c.setExecutor(executor);if(executor instanceof org.bukkit.command.TabCompleter tabs)c.setTabCompleter(tabs);}
}
